        <Button variant="secondary" size="sm" onClick={() => refetch()}>
          {t("common.try_again")}
        </Button>
      </div>
    );
  }

  const handleDeleteUnused = async () => {
    try {
      await deleteUnusedTags.mutateAsync();
      toast.success(t("workspace.tags.all_unused_tags_deleted"));
    } catch {
      toast.error(t("common.something_went_wrong_please_try_again"));
    }
  };

  return (
    <>
      {!isReadOnly && (
        <div className="flex items-center justify-end">
          <Button
            variant="destructive"
            size="sm"
            loading={deleteUnusedTags.isPending}
            onClick={() => setOpenDeleteUnusedDialog(true)}>
            {t("workspace.tags.delete_unused_tags")}
          </Button>
        </div>
      )}
      <SettingsTable
        columns={getTagColumns({ t, workspaceId, tags, isReadOnly })}
        rows={tags}
        getRowId={(tag) => tag.id}
        // Keyed by the id the API returned, so `settings-tags.spec.ts` can address a row without matching
        // on the name — the one thing a rename changes.
        getRowProps={(tag) => ({ "data-testid": `tag-row-${tag.id}` })}
        isLoading={isPending}
        emptyMessage={t("workspace.tags.no_tag_found")}
        aria-label={t("common.tags")}
      />
      <DeleteDialog
        open={openDeleteUnusedDialog}
        setOpen={setOpenDeleteUnusedDialog}
        deleteWhat={t("workspace.tags.delete_unused_tags_title")}
        text={t("workspace.tags.delete_unused_tags_confirmation")}
        onDelete={handleDeleteUnused}
        isDeleting={deleteUnusedTags.isPending}
        buttonLabel={t("common.delete")}
      />
    </>
  );
};
EOF'

